import test from 'node:test';
import assert from 'node:assert/strict';
import { debounce } from '../src/debounce.js';
test('uses latest call and supports cancel', async () => { let seen=[]; const d=debounce((v)=>seen.push(v),15); d(1); d(2); await new Promise(r=>setTimeout(r,30)); assert.deepEqual(seen,[2]); d(3); d.cancel(); await new Promise(r=>setTimeout(r,30)); assert.deepEqual(seen,[2]); });
